  await combos.first().selectOption('731');
  await combos.nth(1).selectOption('567');
  await page.getByRole('button', { name: 'Request Ride' }).click();
  await page.waitForTimeout(8000);
  await page.screenshot({ path: '/tmp/ui2.png', fullPage: true });
